# Let's search all elements for Treasury Bills related content
def search_all(obj, search_term, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            results.extend(search_all(v, search_term, f'{path}.{k}'))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_all(item, search_term, f'{path}[{i}]'))
    elif isinstance(obj, str):
        if search_term.lower() in obj.lower():
            results.append((path, obj[:300]))
    return results

# Search for any 'bills' content
